import React, { useCallback, useRef, useState } from 'react';
import { HostEvent } from '@thoughtspot/visual-embed-sdk';
import { SpotterEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_MODEL_ID } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';

const SUGGESTED_QUESTIONS = [
  'Show bookings by market this month',
  'Revenue by corporate customer and currency',
  'Top routes by booking volume',
];

function UpgradePrompt() {
  const { setTier } = useTier();

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#F7F6FF' }}>
      <div style={{ padding: '2rem 2.5rem 0' }}>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: '#111827', margin: 0 }}>JETT AI</h1>
        <p style={{ fontSize: 13.5, color: '#6B7280', margin: '4px 0 0' }}>
          AI-powered natural language search across your travel data
        </p>
      </div>
      <div style={{ padding: '3rem 2.5rem' }}>
        <div
          style={{
            backgroundColor: '#fff',
            borderRadius: 16,
            padding: '3.5rem 2.5rem',
            textAlign: 'center',
            maxWidth: 520,
            margin: '0 auto',
            border: '1px solid #E5E7EB',
          }}
        >
          <div
            style={{
              width: 68,
              height: 68,
              borderRadius: '50%',
              backgroundColor: '#EDE9FE',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              margin: '0 auto 1.5rem',
            }}
          >
            <svg width="30" height="30" viewBox="0 0 18 18" fill="none">
              <circle cx="9" cy="9" r="7" stroke="#7C3AED" strokeWidth="1.5"/>
              <circle cx="9" cy="9" r="3" fill="#7C3AED"/>
            </svg>
          </div>
          <h2 style={{ fontSize: 21, fontWeight: 700, color: '#111827', margin: '0 0 8px' }}>
            Upgrade to Pro
          </h2>
          <p style={{ fontSize: 14.5, color: '#6B7280', lineHeight: 1.6, margin: '0 0 1.5rem' }}>
            JETT AI lets you ask questions in plain English and get instant answers from your travel data. Available on the <strong style={{ color: '#111827' }}>Pro</strong> tier.
          </p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10, alignItems: 'center' }}>
            <button
              onClick={() => setTier('Pro')}
              style={{
                backgroundColor: '#7C3AED',
                color: '#fff',
                border: 'none',
                padding: '11px 32px',
                borderRadius: 8,
                fontSize: 14.5,
                fontWeight: 600,
                cursor: 'pointer',
              }}
            >
              Upgrade to Pro
            </button>
            <span style={{ fontSize: 12, color: '#9CA3AF' }}>
              Includes AI Search, AI Highlights, and SpotIQ Analysis
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

export default function Spotter() {
  const [embedError, setEmbedError] = useState<string | null>(null);
  const { spotterEnabled } = useTier();
  const embedRef = useRef<any>(null);

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    const msg =
      err?.data?.errorMessage ||
      err?.message ||
      (typeof err === 'object' ? JSON.stringify(err) : String(err));
    setEmbedError(msg);
    console.error('[ThoughtSpot Spotter]', err);
  }, []);

  const handleSuggestion = (query: string) => {
    embedRef.current?.trigger(HostEvent.SpotterSearch, {
      query,
      executeSearch: true,
    });
  };

  if (!spotterEnabled) {
    return <UpgradePrompt />;
  }

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#F7F6FF' }}>
      <div style={{ padding: '2rem 2.5rem 0' }}>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: '#111827', margin: 0 }}>JETT AI</h1>
        <p style={{ fontSize: 13.5, color: '#6B7280', margin: '4px 0 0' }}>
          Use natural language to search across your travel spend, flight data, and more
        </p>
      </div>

      {/* Suggested questions */}
      <div style={{ padding: '1rem 2.5rem 0', display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
        <span style={{ fontSize: 12, fontWeight: 500, color: '#9CA3AF', whiteSpace: 'nowrap' }}>
          Try asking:
        </span>
        {SUGGESTED_QUESTIONS.map((q) => (
          <button
            key={q}
            onClick={() => handleSuggestion(q)}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 6,
              backgroundColor: '#ffffff',
              border: '1px solid #E5E7EB',
              borderRadius: 20,
              padding: '6px 14px',
              fontSize: 13,
              color: '#5B21B6',
              fontWeight: 500,
              cursor: 'pointer',
              transition: 'all 0.15s ease',
              whiteSpace: 'nowrap',
            }}
            onMouseEnter={e => {
              (e.currentTarget as HTMLButtonElement).style.backgroundColor = '#EDE9FE';
              (e.currentTarget as HTMLButtonElement).style.borderColor = '#A78BFA';
            }}
            onMouseLeave={e => {
              (e.currentTarget as HTMLButtonElement).style.backgroundColor = '#ffffff';
              (e.currentTarget as HTMLButtonElement).style.borderColor = '#E5E7EB';
            }}
          >
            <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
              <circle cx="6" cy="6" r="5" stroke="#7C3AED" strokeWidth="1.2"/>
              <circle cx="6" cy="6" r="2" fill="#7C3AED"/>
            </svg>
            {q}
          </button>
        ))}
      </div>

      <div style={{ padding: '1rem 2.5rem 2rem' }}>
        {embedError && (
          <div
            role="alert"
            style={{
              marginBottom: '1rem',
              padding: '0.75rem 1rem',
              background: '#FEF2F2',
              border: '1px solid #FECACA',
              borderRadius: 8,
              fontSize: 14,
              color: '#991B1B',
            }}
          >
            <strong>Embed error:</strong> {embedError}
          </div>
        )}

        <div
          style={{
            backgroundColor: '#fff',
            borderRadius: 12,
            overflow: 'hidden',
            border: '1px solid #E5E7EB',
            minHeight: 'calc(100vh - 220px)',
          }}
        >
          <SpotterEmbed
            ref={embedRef}
            worksheetId={THOUGHTSPOT_MODEL_ID}
            onError={onError}
            hideSampleQuestions={true}
            style={{ width: '100%', height: 'calc(100vh - 220px)' }}
            customizations={{
              iconSpriteUrl: 'https://cdn.jsdelivr.net/gh/CamTS256/icon-store/robot11.svg',
            }}
          />
        </div>
      </div>
    </div>
  );
}
